package com.batiles;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.awt.Color;
import java.util.List;
import org.junit.Test;
import org.junit.experimental.runners.Enclosed;
import net.runelite.http.api.RuneLiteAPI;
import org.junit.runner.RunWith;

@RunWith(Enclosed.class)
public class TileExportTest
{
	// the Gson instance RuneLite injects into plugins
	private static final Gson GSON = RuneLiteAPI.GSON;
	private static final StrategyPreset PRESET = new StrategyPreset("p1", "Stack", 3, "d");
	private static final StrategyPreset OTHER_PRESET = new StrategyPreset("p2", "Split", 3, "d");
	private static final GroundMarkerPoint BASE = new GroundMarkerPoint(7509, 30, 28, 0, Color.RED, "A", List.of(3), List.of("d"));
	private static final GroundMarkerPoint PRESET_TILE = BASE.withPresetId("p1");

	// spans TileExport.of, toJson and fromJson
	public static class RoundTrip
	{
		@Test
		public void roundTripsTilesWithPresets()
		{
			TileExport export = TileExport.of(List.of(BASE, PRESET_TILE), List.of(PRESET, OTHER_PRESET));
			TileExport imported = TileExport.fromJson(GSON, export.toJson(GSON));
			assertEquals(List.of(BASE, PRESET_TILE), imported.getTiles());
			assertEquals(List.of(PRESET), imported.getPresets());
		}

		@Test
		public void roundTripsTilesWithoutPresets()
		{
			TileExport export = TileExport.of(List.of(BASE), List.of(PRESET));
			TileExport imported = TileExport.fromJson(GSON, export.toJson(GSON));
			assertEquals(List.of(BASE), imported.getTiles());
			assertEquals(List.of(), imported.getPresets());
		}
	}

	public static class Of
	{
		@Test
		public void includesOnlyReferencedPresets()
		{
			assertEquals(List.of(PRESET), TileExport.of(List.of(PRESET_TILE), List.of(PRESET, OTHER_PRESET)).getPresets());
		}
	}

	public static class ToJson
	{
		@Test
		public void withoutPresetsWritesTheLegacyArrayFormat()
		{
			assertTrue(TileExport.of(List.of(BASE), List.of()).toJson(GSON).startsWith("["));
		}

		@Test
		public void withPresetsWritesAnObject()
		{
			assertTrue(TileExport.of(List.of(PRESET_TILE), List.of(PRESET)).toJson(GSON).startsWith("{"));
		}
	}

	public static class FromJson
	{
		@Test
		public void readsTilesExportedByOlderVersions()
		{
			String legacy = "[{\"regionId\":7509,\"regionX\":30,\"regionY\":28,\"z\":0,"
					+ "\"color\":\"#FFFF0000\",\"label\":\"A\",\"waves\":[3],\"roles\":[\"d\"]}]";
			TileExport imported = TileExport.fromJson(GSON, legacy);
			assertEquals(List.of(BASE), imported.getTiles());
		}

		@Test
		public void dropsPresetTilesWhosePresetIsMissing()
		{
			String json = GSON.toJson(new TileExport(List.of(BASE, BASE.withPresetId("missing")), List.of()));
			assertEquals(List.of(BASE), TileExport.fromJson(GSON, json).getTiles());
		}

		@Test(expected = JsonParseException.class)
		public void rejectsNonExports()
		{
			TileExport.fromJson(GSON, "\"hello\"");
		}

		@Test(expected = JsonParseException.class)
		public void rejectsEmptyText()
		{
			TileExport.fromJson(GSON, "");
		}
	}
}

package com.batiles;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;
import org.junit.experimental.runners.Enclosed;
import org.junit.runner.RunWith;

/**
 * Pins the walkable-tile tables. The counts were cross-checked against the BA simulators' collision data
 * (every tile without a full movement-blocking flag), which matches tile for tile.
 */
@RunWith(Enclosed.class)
public class BaArenaMapTopologyTest
{
	private static int usableTiles(ArenaMapLayout layout)
	{
		int count = 0;
		for (int x = 0; x < BaArenaMapTopology.WIDTH; x++)
		{
			for (int y = 0; y < BaArenaMapTopology.HEIGHT; y++)
			{
				if (BaArenaMapTopology.isUsableTile(layout, x, y))
				{
					count++;
				}
			}
		}
		return count;
	}

	public static class IsUsableTile
	{
		@Test
		public void usableTileCountsArePinned()
		{
			assertEquals(1070, usableTiles(ArenaMapLayout.WAVES_1_TO_9));
			assertEquals(1117, usableTiles(ArenaMapLayout.WAVE_10));
		}

		@Test
		public void startTilesAreUsable()
		{
			assertTrue(BaArenaMapTopology.isUsableTile(ArenaMapLayout.WAVES_1_TO_9, 31, 10));
			assertTrue(BaArenaMapTopology.isUsableTile(ArenaMapLayout.WAVE_10, 30, 10));
		}

		@Test
		public void outsideTheArenaIsNotUsable()
		{
			assertFalse(BaArenaMapTopology.isUsableTile(ArenaMapLayout.WAVES_1_TO_9, 0, 0));
			assertFalse(BaArenaMapTopology.isUsableTile(ArenaMapLayout.WAVES_1_TO_9, -1, 10));
			assertFalse(BaArenaMapTopology.isUsableTile(ArenaMapLayout.WAVES_1_TO_9, 64, 10));
		}
	}
}

package com.batiles;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.List;
import org.junit.Test;
import org.junit.experimental.runners.Enclosed;
import org.junit.runner.RunWith;

/**
 * Pins the arena coordinate mapping. These values must match where BA Tiles marked in game are stored
 * (the instance template coordinates), and the mapping used by the BA simulators' ground marker import/export.
 */
@RunWith(Enclosed.class)
public class ArenaMapLayoutTest
{
	public static class FromWave
	{
		@Test
		public void wavesOneToNineShareAnArenaAndWaveTenHasItsOwn()
		{
			for (int wave = 1; wave <= 9; wave++)
			{
				assertEquals(ArenaMapLayout.WAVES_1_TO_9, ArenaMapLayout.fromWave(wave));
			}
			assertEquals(ArenaMapLayout.WAVE_10, ArenaMapLayout.fromWave(10));
		}
	}

	public static class GetRegionId
	{
		@Test
		public void regionIdsArePinned()
		{
			assertEquals(7509, ArenaMapLayout.WAVES_1_TO_9.getRegionId());
			assertEquals(7508, ArenaMapLayout.WAVE_10.getRegionId());
		}
	}

	public static class ToRegionY
	{
		@Test
		public void mapRowZeroIsRegionRowEight()
		{
			assertEquals(8, ArenaMapLayout.WAVES_1_TO_9.toRegionY(0));
			assertEquals(30, ArenaMapLayout.WAVES_1_TO_9.toRegionX(30));
		}
	}

	public static class Contains
	{
		@Test
		public void requiresTheLayoutsRegionAndPlaneZero()
		{
			assertTrue(ArenaMapLayout.WAVES_1_TO_9.contains(new GroundMarkerPoint(7509, 30, 28, 0, null, null, null, null)));
			assertFalse(ArenaMapLayout.WAVES_1_TO_9.contains(new GroundMarkerPoint(7508, 30, 28, 0, null, null, null, null)));
			assertFalse(ArenaMapLayout.WAVES_1_TO_9.contains(new GroundMarkerPoint(7509, 30, 28, 1, null, null, null, null)));
			assertFalse(ArenaMapLayout.WAVES_1_TO_9.contains(new GroundMarkerPoint(7509, 30, 7, 0, null, null, List.of(), List.of())));
		}
	}

	public static class ToMapY
	{
		@Test
		public void invertsToRegionY()
		{
			GroundMarkerPoint point = new GroundMarkerPoint(7509, 12, 40, 0, null, null, null, null);
			assertEquals(32, ArenaMapLayout.WAVES_1_TO_9.toMapY(point));
			assertEquals(12, ArenaMapLayout.WAVES_1_TO_9.toMapX(point));
		}
	}
}

package com.batiles;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.awt.Color;
import java.util.List;
import org.junit.Test;
import org.junit.experimental.runners.Enclosed;
import org.junit.runner.RunWith;

@RunWith(Enclosed.class)
public class EditorLayersTest
{
	// map tile (30, 20) is region tile (30, 28)
	private static final GroundMarkerPoint BASE_W3_D = new GroundMarkerPoint(7509, 30, 28, 0, Color.RED, null, List.of(3), List.of("d"));
	private static final GroundMarkerPoint BASE_ALL = new GroundMarkerPoint(7509, 30, 28, 0, Color.RED, null, null, null);
	private static final GroundMarkerPoint BASE_W4 = new GroundMarkerPoint(7509, 30, 28, 0, Color.RED, null, List.of(4), List.of("d"));
	private static final GroundMarkerPoint PRESET_P1 = new GroundMarkerPoint(7509, 30, 28, 0, Color.RED, null, List.of(3), List.of("d"), "p1");
	private static final GroundMarkerPoint PRESET_P2 = new GroundMarkerPoint(7509, 30, 28, 0, Color.RED, null, List.of(3), List.of("d"), "p2");
	private static final GroundMarkerPoint WAVE_10_TILE = new GroundMarkerPoint(7508, 30, 28, 0, Color.RED, null, List.of(10), List.of("d"));
	private static final List<GroundMarkerPoint> ALL = List.of(BASE_W3_D, BASE_ALL, BASE_W4, PRESET_P1, PRESET_P2, WAVE_10_TILE);

	public static class IsShown
	{
		@Test
		public void showsBaseTilesOfTheWaveAndRoleAndTheActivePresetsTiles()
		{
			EditorLayers layers = new EditorLayers(3, "d", "p1", true);
			assertTrue(layers.isShown(BASE_W3_D));
			assertTrue(layers.isShown(BASE_ALL));
			assertTrue(layers.isShown(PRESET_P1));
			assertFalse(layers.isShown(BASE_W4));
			assertFalse(layers.isShown(PRESET_P2));
			assertFalse(layers.isShown(WAVE_10_TILE));
		}

		@Test
		public void waveTenShowsOnlyTheWaveTenRegion()
		{
			EditorLayers layers = new EditorLayers(10, "d", null, false);
			assertTrue(layers.isShown(WAVE_10_TILE));
			assertFalse(layers.isShown(BASE_ALL));
		}
	}

	public static class IsEditable
	{
		@Test
		public void editingPresetMakesOnlyPresetTilesEditable()
		{
			EditorLayers layers = new EditorLayers(3, "d", "p1", true);
			assertTrue(layers.isEditable(PRESET_P1));
			assertFalse(layers.isEditable(BASE_W3_D));
		}

		@Test
		public void editingBaseMakesOnlyBaseTilesEditable()
		{
			EditorLayers layers = new EditorLayers(3, "d", "p1", false);
			assertFalse(layers.isEditable(PRESET_P1));
			assertTrue(layers.isEditable(BASE_W3_D));
		}

		@Test
		public void withoutActivePresetBaseTilesAreEdited()
		{
			EditorLayers layers = new EditorLayers(3, "d", null, true);
			assertFalse(layers.isEditingPreset());
			assertTrue(layers.isEditable(BASE_W3_D));
		}
	}

	public static class MapMarkers
	{
		@Test
		public void dimsTheLayerNotBeingEditedAndMarksTheSelection()
		{
			EditorLayers layers = new EditorLayers(3, "d", "p1", true);
			List<ArenaMapPanel.MapMarker> markers = layers.mapMarkers(ALL, PRESET_P1);
			assertEquals(List.of(
					new ArenaMapPanel.MapMarker(BASE_W3_D, true, false),
					new ArenaMapPanel.MapMarker(BASE_ALL, true, false),
					new ArenaMapPanel.MapMarker(PRESET_P1, false, true)), markers);
		}
	}

	public static class EditableAt
	{
		@Test
		public void returnsEditableTilesOnTheMapTile()
		{
			EditorLayers layers = new EditorLayers(3, "d", "p1", false);
			assertEquals(List.of(BASE_W3_D, BASE_ALL), layers.editableAt(ALL, 30, 20));
			assertEquals(List.of(), layers.editableAt(ALL, 31, 20));
		}
	}

	public static class NewPoint
	{
		@Test
		public void newBaseTileIsForThisWaveAndRoleOnly()
		{
			GroundMarkerPoint point = new EditorLayers(3, "d", "p1", false).newPoint(30, 20, Color.BLUE);
			assertEquals(new GroundMarkerPoint(7509, 30, 28, 0, Color.BLUE, null, List.of(3), List.of("d"), null), point);
		}

		@Test
		public void newPresetTileBelongsToTheActivePreset()
		{
			GroundMarkerPoint point = new EditorLayers(3, "d", "p1", true).newPoint(30, 20, Color.BLUE);
			assertEquals("p1", point.getPresetId());
		}

		@Test
		public void waveTenTilesGoInTheWaveTenRegion()
		{
			GroundMarkerPoint point = new EditorLayers(10, "a", null, true).newPoint(30, 20, Color.BLUE);
			assertEquals(7508, point.getRegionId());
			assertNull(point.getPresetId());
		}
	}
}

