package com.batiles;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * The two Barbarian Assault arena layouts, and the mapping between arena map coordinates and the instance template
 * coordinates BA Tiles are stored in (what {@link net.runelite.api.coords.WorldPoint#fromLocalInstance} returns).
 */
@Getter
@RequiredArgsConstructor
enum ArenaMapLayout
{
	WAVES_1_TO_9("Waves 1-9", 7509),
	WAVE_10("Wave 10", 7508);

	static final int WIDTH = 64;
	static final int HEIGHT = 48;
	private static final int REGION_Y_OFFSET = 8;
	static final int[] REGION_IDS = {WAVES_1_TO_9.regionId, WAVE_10.regionId};

	private final String displayName;
	private final int regionId;

	static ArenaMapLayout fromWave(int wave)
	{
		return wave == 10 ? WAVE_10 : WAVES_1_TO_9;
	}

	int toRegionX(int mapX)
	{
		return mapX;
	}

	int toRegionY(int mapY)
	{
		return mapY + REGION_Y_OFFSET;
	}

	int toMapX(GroundMarkerPoint point)
	{
		return point.getRegionX();
	}

	int toMapY(GroundMarkerPoint point)
	{
		return point.getRegionY() - REGION_Y_OFFSET;
	}

	boolean contains(GroundMarkerPoint point)
	{
		if (point == null || point.getRegionId() != regionId || point.getZ() != 0)
		{
			return false;
		}
		int x = toMapX(point);
		int y = toMapY(point);
		return x >= 0 && x < WIDTH && y >= 0 && y < HEIGHT;
	}

	boolean isAt(GroundMarkerPoint point, int mapX, int mapY)
	{
		return contains(point) && toMapX(point) == mapX && toMapY(point) == mapY;
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.batiles;

import java.awt.BorderLayout;
import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.awt.GridLayout;
import java.awt.Insets;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Supplier;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

/**
 * Sidebar panel: for a role, switch the active strategy preset of each wave; and open the tile map editor.
 */
class BATilesPanel extends PluginPanel
{
	private static final int WAVES = 10;
	private static final String SHOW_BASE_TOOLTIP = "Show tiles that are not part of a preset while this wave's preset is active";

	private final BATilesStore store;
	private final Supplier<TileMapEditor> editor;
	private final Runnable storeListener = () -> SwingUtilities.invokeLater(this::refresh);

	private final JComboBox<BARole> roleCombo = new JComboBox<>(BARole.values());
	private final List<JComboBox<Object>> presetCombos = new ArrayList<>();
	private final List<JCheckBox> showBaseBoxes = new ArrayList<>();
	// the editor opens on the in-game wave
	private int currentWave = 1;
	private boolean refreshing;

	BATilesPanel(BATilesStore store, Supplier<TileMapEditor> editor)
	{
		this.store = store;
		this.editor = editor;

		setLayout(new BorderLayout());
		setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

		JPanel top = new JPanel(new GridLayout(0, 1, 0, 6));

		JLabel title = new JLabel("BA Tiles");
		title.setForeground(ColorScheme.BRAND_ORANGE);
		top.add(title);

		JButton openEditor = new JButton("Open tile map editor");
		openEditor.addActionListener(e -> editor.get().open(currentWave, role()));
		top.add(openEditor);

		top.add(new JLabel("Active strategy presets"));
		top.add(roleCombo);

		JPanel waves = new JPanel(new GridBagLayout());
		GridBagConstraints c = new GridBagConstraints();
		c.insets = new Insets(0, 0, 6, 6);
		c.fill = GridBagConstraints.HORIZONTAL;

		c.gridy = 0;
		c.gridx = 1;
		waves.add(columnHeader("Preset", null), c);
		c.gridx = 2;
		c.fill = GridBagConstraints.NONE;
		waves.add(columnHeader("Others", SHOW_BASE_TOOLTIP), c);
		c.fill = GridBagConstraints.HORIZONTAL;

		for (int i = 0; i < WAVES; i++)
		{
			int wave = i + 1;
			JLabel label = new JLabel("Wave " + wave);
			JComboBox<Object> combo = new JComboBox<>();
			combo.addActionListener(e -> onPresetSelected(wave, combo));
			presetCombos.add(combo);
			JCheckBox showBase = new JCheckBox();
			showBase.setToolTipText(SHOW_BASE_TOOLTIP);
			showBase.addActionListener(e ->
			{
				if (!refreshing)
				{
					store.setShowBaseWithPreset(wave, role(), showBase.isSelected());
				}
			});
			showBaseBoxes.add(showBase);

			c.gridy = i + 1;
			c.gridx = 0;
			c.weightx = 0;
			waves.add(label, c);
			c.gridx = 1;
			c.weightx = 1;
			waves.add(combo, c);
			c.gridx = 2;
			c.weightx = 0;
			c.fill = GridBagConstraints.NONE;
			waves.add(showBase, c);
			c.fill = GridBagConstraints.HORIZONTAL;
		}

		JLabel help = new JLabel("<html>A preset's tiles are only shown while it is the active preset for its wave and role."
				+ "<br><br><b>Others</b>: also show tiles that are not part of a preset while a preset is active."
				+ " They are always shown while no preset is.</html>");
		help.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

		JPanel column = new JPanel(new BorderLayout(0, 8));
		column.add(top, BorderLayout.NORTH);
		column.add(waves, BorderLayout.CENTER);
		column.add(help, BorderLayout.SOUTH);
		add(column, BorderLayout.NORTH);

		roleCombo.addActionListener(e -> refresh());
		store.addListener(storeListener);
		refresh();
	}

	void shutDown()
	{
		store.removeListener(storeListener);
	}

	/**
	 * Called when the in-game wave or role changes.
	 */
	void onGameStateChanged(int wave, String role)
	{
		SwingUtilities.invokeLater(() -> currentWave = wave);
	}

	private static JLabel columnHeader(String text, String tooltip)
	{
		JLabel header = new JLabel(text);
		header.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		header.setToolTipText(tooltip);
		return header;
	}

	private String role()
	{
		return ((BARole) roleCombo.getSelectedItem()).getCode();
	}

	private void onPresetSelected(int wave, JComboBox<Object> combo)
	{
		if (refreshing)
		{
			return;
		}
		Object item = combo.getSelectedItem();
		store.setActivePreset(wave, role(), item instanceof PresetOption ? ((PresetOption) item).getPreset() : null);
	}

	private void refresh()
	{
		refreshing = true;
		try
		{
			for (int i = 0; i < WAVES; i++)
			{
				int wave = i + 1;
				JComboBox<Object> combo = presetCombos.get(i);
				List<StrategyPreset> presets = store.getPresets(wave, role());
				String activeId = store.getActivePresetId(wave, role());
				combo.removeAllItems();
				combo.addItem(PresetOption.NO_PRESET);
				Object active = PresetOption.NO_PRESET;
				for (StrategyPreset preset : presets)
				{
					PresetOption option = new PresetOption(preset);
					combo.addItem(option);
					if (preset.getId().equals(activeId))
					{
						active = option;
					}
				}
				combo.setSelectedItem(active);
				// nothing to choose between, and no preset to show other tiles alongside, until the wave has a preset for this role
				combo.setEnabled(!presets.isEmpty());
				JCheckBox showBase = showBaseBoxes.get(i);
				showBase.setSelected(store.isShowBaseWithPreset(wave, role()));
				showBase.setEnabled(!presets.isEmpty());
			}
		}
		finally
		{
			refreshing = false;
		}
	}
}

package com.batiles;

import java.awt.Color;
import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import java.util.stream.Collectors;
import javax.annotation.Nullable;
import lombok.Value;

/**
 * What the tile map editor shows and edits for one wave / role: the tiles of the active preset (if any) and the tiles
 * that are not part of any preset. One of the two is the layer being edited; the other is shown dimmed for context.
 */
@Value
class EditorLayers
{
	int wave;
	String role;
	/**
	 * The active preset for the wave and role, or null if none is active.
	 */
	@Nullable
	String activePresetId;
	/**
	 * Whether the preset layer (rather than the non-preset layer) is being edited. Ignored without an active preset.
	 */
	boolean editingPreset;

	ArenaMapLayout layout()
	{
		return ArenaMapLayout.fromWave(wave);
	}

	boolean isEditingPreset()
	{
		return editingPreset && activePresetId != null;
	}

	/**
	 * @return whether the point belongs on this wave / role's map, in either layer
	 */
	boolean isShown(GroundMarkerPoint point)
	{
		return isPresetLayer(point) || isBaseLayer(point);
	}

	/**
	 * @return whether the point is in the layer being edited
	 */
	boolean isEditable(GroundMarkerPoint point)
	{
		return isEditingPreset() ? isPresetLayer(point) : isBaseLayer(point);
	}

	private boolean isPresetLayer(GroundMarkerPoint point)
	{
		return activePresetId != null && activePresetId.equals(point.getPresetId()) && layout().contains(point);
	}

	private boolean isBaseLayer(GroundMarkerPoint point)
	{
		return !point.isPresetTile()
				&& layout().contains(point)
				&& (point.getWaves() == null || point.getWaves().contains(wave))
				&& (point.getRoles() == null || point.getRoles().contains(role));
	}

	List<ArenaMapPanel.MapMarker> mapMarkers(Collection<GroundMarkerPoint> points, @Nullable GroundMarkerPoint selected)
	{
		List<ArenaMapPanel.MapMarker> markers = new ArrayList<>();
		for (GroundMarkerPoint point : points)
		{
			if (isShown(point))
			{
				boolean editable = isEditable(point);
				markers.add(new ArenaMapPanel.MapMarker(point, !editable, editable && point.equals(selected)));
			}
		}
		return markers;
	}

	/**
	 * @return the editable points on the given map tile, in stored order
	 */
	List<GroundMarkerPoint> editableAt(Collection<GroundMarkerPoint> points, int mapX, int mapY)
	{
		return points.stream()
				.filter(p -> layout().isAt(p, mapX, mapY) && isEditable(p))
				.collect(Collectors.toList());
	}

	/**
	 * Creates a new point on the given map tile in the layer being edited.
	 * A non-preset tile starts out shown only for this wave and role; that can be widened afterwards.
	 */
	GroundMarkerPoint newPoint(int mapX, int mapY, Color color)
	{
		ArenaMapLayout layout = layout();
		return new GroundMarkerPoint(layout.getRegionId(), layout.toRegionX(mapX), layout.toRegionY(mapY), 0, color, null,
				List.of(wave), List.of(role), isEditingPreset() ? activePresetId : null);
	}
}

package com.batiles;

import com.google.common.base.Strings;
import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.List;
import java.util.Objects;
import java.util.Optional;
import java.util.UUID;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.function.UnaryOperator;
import java.util.stream.Collectors;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Persists BA Tiles and strategy presets in the RuneLite config, and notifies listeners when they change.
 */
@Slf4j
@Singleton
class BATilesStore
{
	private static final String REGION_PREFIX = "region_";
	private static final String PRESETS_KEY = "presets";
	private static final String ACTIVE_PRESET_PREFIX = "activePreset_";
	private static final String SHOW_BASE_WITH_PRESET_PREFIX = "showBaseWithPreset_";

	private final ConfigManager configManager;
	private final Gson gson;
	private final List<Runnable> listeners = new CopyOnWriteArrayList<>();

	@Inject
	BATilesStore(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	void addListener(Runnable listener)
	{
		listeners.add(listener);
	}

	void removeListener(Runnable listener)
	{
		listeners.remove(listener);
	}

	/**
	 * Notifies listeners that tiles or presets changed. Called after every mutation made through this store; also
	 * called by the plugin when the config changes underneath it (e.g. a profile switch).
	 */
	void fireChanged()
	{
		for (Runnable listener : listeners)
		{
			listener.run();
		}
	}

	// ---- tiles ----

	List<GroundMarkerPoint> getPoints(int regionId)
	{
		String json = configManager.getConfiguration(BATilesConfig.BA_TILES_CONFIG_GROUP, REGION_PREFIX + regionId);
		if (Strings.isNullOrEmpty(json))
		{
			return Collections.emptyList();
		}

		// CHECKSTYLE:OFF
		List<GroundMarkerPoint> points = gson.fromJson(json, new TypeToken<List<GroundMarkerPoint>>(){}.getType());
		// CHECKSTYLE:ON
		return points == null ? Collections.emptyList() : points;
	}

	void savePoints(int regionId, @Nullable Collection<GroundMarkerPoint> points)
	{
		writePoints(regionId, points);
		fireChanged();
	}

	private void writePoints(int regionId, @Nullable Collection<GroundMarkerPoint> points)
	{
		if (points == null || points.isEmpty())
		{
			configManager.unsetConfiguration(BATilesConfig.BA_TILES_CONFIG_GROUP, REGION_PREFIX + regionId);
		}
		else
		{
			configManager.setConfiguration(BATilesConfig.BA_TILES_CONFIG_GROUP, REGION_PREFIX + regionId, gson.toJson(points));
		}
	}

	void addPoint(GroundMarkerPoint point)
	{
		List<GroundMarkerPoint> points = new ArrayList<>(getPoints(point.getRegionId()));
		points.add(point);
		savePoints(point.getRegionId(), points);
	}

	void removePoint(GroundMarkerPoint point)
	{
		List<GroundMarkerPoint> points = new ArrayList<>(getPoints(point.getRegionId()));
		points.remove(point);
		savePoints(point.getRegionId(), points);
	}

	/**
	 * Replaces {@code existing} with {@code update.apply(existing)}, keeping its position in the region's list.
	 *
	 * @return the updated point, or {@code existing} if it is no longer stored
	 */
	GroundMarkerPoint updatePoint(GroundMarkerPoint existing, UnaryOperator<GroundMarkerPoint> update)
	{
		List<GroundMarkerPoint> points = new ArrayList<>(getPoints(existing.getRegionId()));
		int index = points.indexOf(existing);
		if (index < 0)
		{
			return existing;
		}

		GroundMarkerPoint updated = update.apply(existing);
		points.set(index, updated);
		savePoints(existing.getRegionId(), points);
		return updated;
	}

	// ---- presets ----

	List<StrategyPreset> getPresets()
	{
		String json = configManager.getConfiguration(BATilesConfig.BA_TILES_CONFIG_GROUP, PRESETS_KEY);
		if (Strings.isNullOrEmpty(json))
		{
			return Collections.emptyList();
		}

		// CHECKSTYLE:OFF
		List<StrategyPreset> presets = gson.fromJson(json, new TypeToken<List<StrategyPreset>>(){}.getType());
		// CHECKSTYLE:ON
		return presets == null ? Collections.emptyList() : presets;
	}

	List<StrategyPreset> getPresets(int wave, String role)
	{
		return getPresets().stream()
				.filter(p -> p.getWave() == wave && p.getRole().equals(role))
				.collect(Collectors.toList());
	}

	Optional<StrategyPreset> getPreset(@Nullable String id)
	{
		return getPresets().stream().filter(p -> p.getId().equals(id)).findFirst();
	}

	private void savePresets(List<StrategyPreset> presets)
	{
		if (presets.isEmpty())
		{
			configManager.unsetConfiguration(BATilesConfig.BA_TILES_CONFIG_GROUP, PRESETS_KEY);
		}
		else
		{
			configManager.setConfiguration(BATilesConfig.BA_TILES_CONFIG_GROUP, PRESETS_KEY, gson.toJson(presets));
		}
	}

	StrategyPreset createPreset(String name, int wave, String role)
	{
		StrategyPreset preset = new StrategyPreset(UUID.randomUUID().toString(), name, wave, role);
		List<StrategyPreset> presets = new ArrayList<>(getPresets());
		presets.add(preset);
		savePresets(presets);
		fireChanged();
		return preset;
	}

	/**
	 * Adds presets that are not already stored (matched by id), e.g. presets that arrived with an import.
	 *
	 * @return the number of presets added
	 */
	int addPresetsIfAbsent(Collection<StrategyPreset> toAdd)
	{
		List<StrategyPreset> presets = new ArrayList<>(getPresets());
		int added = 0;
		for (StrategyPreset preset : toAdd)
		{
			if (presets.stream().noneMatch(p -> p.getId().equals(preset.getId())))
			{
				presets.add(preset);
				added++;
			}
		}

		if (added > 0)
		{
			savePresets(presets);
			fireChanged();
		}
		return added;
	}

	void renamePreset(StrategyPreset preset, String name)
	{
		List<StrategyPreset> presets = getPresets().stream()
				.map(p -> p.getId().equals(preset.getId()) ? p.withName(name) : p)
				.collect(Collectors.toList());
		savePresets(presets);
		fireChanged();
	}

	/**
	 * Deletes a preset along with all of its tiles in the given regions.
	 */
	void deletePreset(StrategyPreset preset, int[] regionIds)
	{
		for (int regionId : regionIds)
		{
			List<GroundMarkerPoint> points = getPoints(regionId);
			List<GroundMarkerPoint> kept = points.stream()
					.filter(p -> !preset.getId().equals(p.getPresetId()))
					.collect(Collectors.toList());
			if (kept.size() != points.size())
			{
				writePoints(regionId, kept);
			}
		}

		List<StrategyPreset> presets = getPresets().stream()
				.filter(p -> !p.getId().equals(preset.getId()))
				.collect(Collectors.toList());
		savePresets(presets);

		if (preset.getId().equals(getActivePresetId(preset.getWave(), preset.getRole())))
		{
			configManager.unsetConfiguration(BATilesConfig.BA_TILES_CONFIG_GROUP, activePresetKey(preset.getWave(), preset.getRole()));
		}
		fireChanged();
	}

	// ---- active preset selection ----

	private static String activePresetKey(int wave, String role)
	{
		return ACTIVE_PRESET_PREFIX + wave + "_" + role;
	}

	/**
	 * @return the id of the active preset for the wave and role, or null if tiles are shown without a preset
	 */
	@Nullable
	String getActivePresetId(int wave, String role)
	{
		return Strings.emptyToNull(configManager.getConfiguration(BATilesConfig.BA_TILES_CONFIG_GROUP, activePresetKey(wave, role)));
	}

	void setActivePreset(int wave, String role, @Nullable StrategyPreset preset)
	{
		if (Objects.equals(preset == null ? null : preset.getId(), getActivePresetId(wave, role)))
		{
			return;
		}

		if (preset == null)
		{
			configManager.unsetConfiguration(BATilesConfig.BA_TILES_CONFIG_GROUP, activePresetKey(wave, role));
		}
		else
		{
			configManager.setConfiguration(BATilesConfig.BA_TILES_CONFIG_GROUP, activePresetKey(wave, role), preset.getId());
		}
		fireChanged();
	}

	// ---- non-preset tiles while a preset is active ----

	private static String showBaseWithPresetKey(int wave, String role)
	{
		return SHOW_BASE_WITH_PRESET_PREFIX + wave + "_" + role;
	}

	/**
	 * @return whether tiles that are not part of a preset are shown for the wave and role while it has an active
	 *         preset (they are always shown while it has none). Defaults to true.
	 */
	boolean isShowBaseWithPreset(int wave, String role)
	{
		String value = configManager.getConfiguration(BATilesConfig.BA_TILES_CONFIG_GROUP, showBaseWithPresetKey(wave, role));
		return value == null || Boolean.parseBoolean(value);
	}

	void setShowBaseWithPreset(int wave, String role, boolean show)
	{
		if (show == isShowBaseWithPreset(wave, role))
		{
			return;
		}

		if (show)
		{
			configManager.unsetConfiguration(BATilesConfig.BA_TILES_CONFIG_GROUP, showBaseWithPresetKey(wave, role));
		}
		else
		{
			configManager.setConfiguration(BATilesConfig.BA_TILES_CONFIG_GROUP, showBaseWithPresetKey(wave, role), false);
		}
		fireChanged();
	}
}

package com.batiles;

import lombok.AllArgsConstructor;
import lombok.Getter;

@Getter
@AllArgsConstructor
enum BARole
{
    ATTACKER("a", "Attacker"),
    COLLECTOR("c", "Collector"),
    DEFENDER("d", "Defender"),
    HEALER("h", "Healer");

    /**
     * The code stored in {@link GroundMarkerPoint#getRoles()}.
     */
    private final String code;
    private final String displayName;

    static BARole fromCode(String code)
    {
        for (BARole role : values())
        {
            if (role.code.equals(code))
            {
                return role;
            }
        }
        return null;
    }

    @Override
    public String toString()
    {
        return displayName;
    }
}

package com.batiles;

import com.google.common.base.Strings;
import com.google.common.util.concurrent.Runnables;
import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.MenuEntry;
import net.runelite.api.widgets.ComponentID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.game.chatbox.ChatboxPanelManager;
import net.runelite.client.menus.MenuManager;
import net.runelite.client.menus.WidgetMenuOption;

import javax.inject.Inject;
import java.awt.*;
import java.awt.datatransfer.DataFlavor;
import java.awt.datatransfer.StringSelection;
import java.awt.datatransfer.UnsupportedFlavorException;
import java.io.IOException;
import java.util.*;
import java.util.List;
import java.util.function.Function;
import java.util.stream.Collectors;

@Slf4j
class BATilesSharingManager
{
    private static final WidgetMenuOption EXPORT_MARKERS_OPTION = new WidgetMenuOption("Export", "BA Tiles", ComponentID.MINIMAP_WORLDMAP_OPTIONS);
    private static final WidgetMenuOption IMPORT_MARKERS_OPTION = new WidgetMenuOption("Import", "BA Tiles", ComponentID.MINIMAP_WORLDMAP_OPTIONS);
    private static final WidgetMenuOption CLEAR_MARKERS_OPTION = new WidgetMenuOption("Clear", "BA Tiles", ComponentID.MINIMAP_WORLDMAP_OPTIONS);

    private final Client client;
    private final MenuManager menuManager;
    private final ChatMessageManager chatMessageManager;
    private final ChatboxPanelManager chatboxPanelManager;
    private final Gson gson;
    private final BATilesStore store;
    private final ClientThread clientThread;

    @Inject
    private BATilesSharingManager(Client client, MenuManager menuManager,
                                  ChatMessageManager chatMessageManager, ChatboxPanelManager chatboxPanelManager, Gson gson,
                                  BATilesStore store, ClientThread clientThread)
    {
        this.store = store;
        this.clientThread = clientThread;
        this.client = client;
        this.menuManager = menuManager;
        this.chatMessageManager = chatMessageManager;
        this.chatboxPanelManager = chatboxPanelManager;
        this.gson = gson;
    }

    void addImportExportMenuOptions()
    {
        menuManager.addManagedCustomMenu(EXPORT_MARKERS_OPTION, this::exportGroundMarkers);
        menuManager.addManagedCustomMenu(IMPORT_MARKERS_OPTION, this::promptForImport);
    }

    void addClearMenuOption()
    {
        menuManager.addManagedCustomMenu(CLEAR_MARKERS_OPTION, this::promptForClear);
    }

    void removeMenuOptions()
    {
        menuManager.removeManagedCustomMenu(EXPORT_MARKERS_OPTION);
        menuManager.removeManagedCustomMenu(IMPORT_MARKERS_OPTION);
        menuManager.removeManagedCustomMenu(CLEAR_MARKERS_OPTION);
    }

    private void exportGroundMarkers(MenuEntry menuEntry)
    {
        int[] regions = client.getMapRegions();
        if (regions == null)
        {
            return;
        }

        List<GroundMarkerPoint> activePoints = Arrays.stream(regions)
                .mapToObj(regionId -> store.getPoints(regionId).stream())
                .flatMap(Function.identity())
                .collect(Collectors.toList());

        if (activePoints.isEmpty())
        {
            sendChatMessage("You have no BA Tiles to export.");
            return;
        }

        final String exportDump = TileExport.of(activePoints, store.getPresets()).toJson(gson);

        log.debug("Exported BA Tiles: {}", exportDump);

        Toolkit.getDefaultToolkit()
                .getSystemClipboard()
                .setContents(new StringSelection(exportDump), null);
        sendChatMessage(activePoints.size() + " BA Tiles were copied to your clipboard.");
    }

    /**
     * Copies a single strategy preset and its tiles to the clipboard.
     */
    void exportPreset(StrategyPreset preset)
    {
        List<GroundMarkerPoint> presetPoints = Arrays.stream(ArenaMapLayout.REGION_IDS)
                .mapToObj(regionId -> store.getPoints(regionId).stream())
                .flatMap(Function.identity())
                .filter(p -> preset.getId().equals(p.getPresetId()))
                .collect(Collectors.toList());

        final String exportDump = TileExport.of(presetPoints, List.of(preset)).toJson(gson);
        Toolkit.getDefaultToolkit()
                .getSystemClipboard()
                .setContents(new StringSelection(exportDump), null);
        sendChatMessage("Strategy preset \"" + preset.getName() + "\" (" + presetPoints.size()
                + " BA Tiles) was copied to your clipboard.");
    }

    private void promptForImport(MenuEntry menuEntry)
    {
        promptForImport();
    }

    void promptForImport()
    {
        final String clipboardText;
        try
        {
            clipboardText = Toolkit.getDefaultToolkit()
                    .getSystemClipboard()
                    .getData(DataFlavor.stringFlavor)
                    .toString();
        }
        catch (IOException | UnsupportedFlavorException ex)
        {
            sendChatMessage("Unable to read system clipboard.");
            log.warn("error reading clipboard", ex);
            return;
        }

        log.debug("Clipboard contents: {}", clipboardText);
        if (Strings.isNullOrEmpty(clipboardText))
        {
            sendChatMessage("You do not have any BA Tiles copied in your clipboard.");
            return;
        }

        TileExport imported;
        try
        {
            imported = TileExport.fromJson(gson, clipboardText);
        }
        catch (JsonParseException | IllegalStateException e)
        {
            log.debug("Malformed JSON for clipboard import", e);
            sendChatMessage("You do not have any BA Tiles copied in your clipboard.");
            return;
        }

        if (imported.getTiles().isEmpty() && imported.getPresets().isEmpty())
        {
            sendChatMessage("You do not have any BA Tiles copied in your clipboard.");
            return;
        }

        String question = "Are you sure you want to import " + imported.getTiles().size() + " BA Tiles"
                + (imported.getPresets().isEmpty() ? "?" : "<br>and " + imported.getPresets().size() + " strategy preset"
                + (imported.getPresets().size() == 1 ? "?" : "s?"));
        clientThread.invokeLater(() -> chatboxPanelManager.openTextMenuInput(question)
                .option("Yes", () -> importGroundMarkers(imported))
                .option("No", Runnables.doNothing())
                .build());
    }

    private void importGroundMarkers(TileExport imported)
    {
        int addedPresets = store.addPresetsIfAbsent(imported.getPresets());
        List<GroundMarkerPoint> importPoints = imported.getTiles();

        // regions being imported may not be loaded on client,
        // so need to import each bunch directly into the config
        // first, collate the list of unique region ids in the import
        Map<Integer, List<GroundMarkerPoint>> regionGroupedPoints = importPoints.stream()
                .collect(Collectors.groupingBy(GroundMarkerPoint::getRegionId));

        // now import each region into the config
        regionGroupedPoints.forEach((regionId, groupedPoints) ->
        {
            // combine imported points with existing region points
            log.debug("Importing {} points to region {}", groupedPoints.size(), regionId);
            Collection<GroundMarkerPoint> regionPoints = store.getPoints(regionId);

            List<GroundMarkerPoint> mergedList = new ArrayList<>(regionPoints.size() + groupedPoints.size());
            // add existing points
            mergedList.addAll(regionPoints);

            // add new points
            for (GroundMarkerPoint point : groupedPoints)
            {
                // filter out duplicates
                if (!mergedList.contains(point))
                {
                    mergedList.add(point);
                }
            }

            store.savePoints(regionId, mergedList);
        });

        sendChatMessage(importPoints.size() + " BA Tiles"
                + (addedPresets == 0 ? "" : " and " + addedPresets + " strategy preset" + (addedPresets == 1 ? "" : "s"))
                + " were imported from the clipboard.");
    }

    private void promptForClear(MenuEntry entry)
    {
        int[] regions = client.getMapRegions();
        if (regions == null)
        {
            return;
        }

        long numActivePoints = Arrays.stream(regions)
                .mapToLong(regionId -> store.getPoints(regionId).size())
                .sum();

        if (numActivePoints == 0)
        {
            sendChatMessage("You have no BA Tiles to clear.");
            return;
        }

        chatboxPanelManager.openTextMenuInput("Are you sure you want to clear the<br>" + numActivePoints + " currently loaded BA Tiles?")
                .option("Yes", () ->
                {
                    for (int regionId : regions)
                    {
                        store.savePoints(regionId, null);
                    }

                    sendChatMessage(numActivePoints + " BA Tile"
                            + (numActivePoints == 1 ? " was cleared." : "s were cleared."));

                })
                .option("No", Runnables.doNothing())
                .build();
    }

    private void sendChatMessage(final String message)
    {
        chatMessageManager.queue(QueuedMessage.builder()
                .type(ChatMessageType.CONSOLE)
                .runeLiteFormattedMessage(message)
                .build());
    }
}
